namespace sitesplat\bblivechat\event;

use Symfony\Component\EventDispatcher\EventSubscriberInterface;
use Symfony\Component\DependencyInjection\Container;
class listener implements EventSubscriberInterface { protected $auth; protected $cache; protected $config; protected $db; protected $request; protected $template; protected $user; protected $language; public function __construct(\phpbb\auth\auth $auth, \phpbb\cache\driver\driver_interface $cache, \phpbb\config\config $config, \phpbb\db\driver\driver_interface $db, \phpbb\request\request $request, \phpbb\template\template $template, \phpbb\user $user, \phpbb\language\language $language) { $this->auth = $auth; $this->cache = $cache; $this->config = $config; $this->db = $db; $this->request = $request; $this->template = $template; $this->user = $user; $this->language = $language; define('BBLC_EXT_DIR', dirname(__DIR__)); } static public function getSubscribedEvents() { return array( 'core.common' => ['load_addons', -10], 'core.user_setup' => 'load_language', 'core.session_kill_after' => 'remove_user', 'core.avatar_manager_avatar_delete_after' => 'delete_avatar', 'core.acp_users_avatar_sql' => 'update_avatar', 'core.ucp_profile_avatar_sql' => 'update_avatar', 'core.page_header' => 'chatheader', ); } public function load_addons() { static $called; if (empty($called)) { \sitesplat\load_ext_addons('bblivechat'); $called = true; } } public function load_language($event) { static $called; if (empty($called) && defined('ADMIN_START')) { $lang_set_ext = $event['lang_set_ext']; $lang_set_ext[] = array( 'ext_name' => 'sitesplat/bblivechat', 'lang_set' => 'bblivechat', ); $event['lang_set_ext'] = $lang_set_ext; $called = true; } } public function remove_user($event) { $this->db->sql_query("DELETE FROM bblc_online WHERE userID = {$event['user_id']}"); setcookie('bblivechat', '', time() - 86400, $this->config['cookie_path'], $this->config['cookie_domain'], $this->config['cookie_secure']); setcookie('bblc_sid', '', time() - 86400, $this->config['cookie_path'], $this->config['cookie_domain'], $this->config['cookie_secure']); } public function delete_avatar($event) { if ($event['prefix'] === 'user_') { $this->db->sql_query("UPDATE bblc_messages SET ip = '' WHERE userID = {$event['avatar_data']['id']}"); } } public function update_avatar($event) { $avatar = ''; $userdata = array_merge(empty($event['user_row']) ? $this->user->data : $event['user_row'], $event['result']); if (!empty($userdata['user_avatar'])) { $avmax = max($userdata['user_avatar_width'], $userdata['user_avatar_height']); if ($avmax > 64) { $userdata['user_avatar_width'] = floor(($userdata['user_avatar_width'] * 64) / $avmax); $userdata['user_avatar_height'] = floor(($userdata['user_avatar_height'] * 64) / $avmax); } preg_match('`src\="(.*?)"`', phpbb_get_user_avatar($userdata, ''), $matches); if (!empty($matches[1])) { if (substr($matches[1], 0, 2) == '//') { $avatar = 'https:' . $matches[1]; } else { $avatar = str_replace(generate_board_url() . '/', '', $matches[1]); } } } $this->db->sql_query("UPDATE bblc_messages SET ip = '{$avatar}' WHERE userID = {$userdata['user_id']}"); } public function chatheader($event) { if ($this->user->data['is_registered'] && !defined('BBLIVECHAT')) { if (($defaults = $this->cache->get('_bblivechat')) === false) { $sql = 'SELECT config_value FROM ' . CONFIG_TEXT_TABLE . " WHERE config_name = 'bblivechat'"; $result = $this->db->sql_query($sql); $defaults = $this->db->sql_fetchfield('config_value'); $this->db->sql_freeresult($result); $this->cache->put('_bblivechat', $defaults); } $defaults = json_decode($defaults, true); $open = !intval($defaults['settings'][0]) && !empty($defaults['settings'][7]); $chatcount = 0; $chat_ary = $del_ary = []; $sql = 'SELECT b.userId, b.userName, b.`dateTime`, b.ip, u.user_colour FROM bblc_online b, ' . USERS_TABLE . ' u WHERE u.user_id = b.userId'; $result = $this->db->sql_query($sql); while ($row = $this->db->sql_fetchrow($result)) { $id = (int) $row['userId']; $name = ($row['user_colour']) ? '<span style="vertical-align:middle;color:#' . $row['user_colour'] . '">' . $row['userName'] . '</span>' : $row['userName']; $online = strtotime($row['dateTime']); $avatar = ($row['ip']) ? '<img src="' . $row['ip'] . '" style="max-width:24px;max-height:24px"> ' : ''; if ($online < time() - 120 - (60 * $defaults['settings'][7])) { $del_ary[] = $id; if ($this->user->data['user_id'] == $id && $this->request->variable('bblivechat', '', false, \phpbb\request\request_interface::COOKIE)) { setcookie('bblivechat', '', time() - 86400, $this->config['cookie_path'], $this->config['cookie_domain'], $this->config['cookie_secure']); setcookie('bblc_sid', '', time() - 86400, $this->config['cookie_path'], $this->config['cookie_domain'], $this->config['cookie_secure']); } } else { $chat_ary[] = [$name, $avatar, $id]; $chatcount++; } } $this->db->sql_freeresult($result); if (count($del_ary)) { $deldata = implode(',', $del_ary); $this->db->sql_query("DELETE FROM bblc_online WHERE userID IN ({$deldata})"); } } if (!empty($open) && class_exists('\sitesplat\bblc_online\bblivechat', false) && !empty($this->config['bblc_online'])) { \sitesplat\bblc_online\bblivechat::online_list($chatcount, $chat_ary); } } }